  </head>
  <body>
    <div id="root"></div>

    <script>
      const quizData = [
        {
          id: "question-1",
          title: "Which of these are widely used programming languages?",
          helpText: "Select every option that is a programming language.",
          options: ["Python", "HTML", "JavaScript", "SQL"],
          correct: ["Python", "JavaScript", "SQL"],
        },
        {
          id: "question-2",
          title: "Which languages are commonly used for systems programming?",
          options: ["Rust", "C", "CSS", "Go"],
          correct: ["Rust", "C", "Go"],
        },
        {
          id: "question-3",
          title: "Which of these are primarily markup or stylesheet languages?",
          options: ["HTML", "Java", "CSS", "Markdown"],
          correct: ["HTML", "CSS", "Markdown"],
        },
      ];

      function App() {
        return `
          <main class="page">
            <div class="shell">
              <header class="hero">
                <div class="eyebrow">Quiz Builder</div>
                <h1>Computer Languages Quiz</h1>
                <p class="subhead">A clean multi-select quiz with three questions, four choices each, and a modern product-style layout.</p>
              </header>

              <section class="quiz-card">
                <form id="quiz-form" novalidate>
                  <div class="question-list">
                    ${quizData.map((question, index) => QuestionCard(question, index)).join("")}
                  </div>

                  <div class="actions">
                    <button type="submit" class="submit-btn">Submit quiz</button>
                  </div>

                  <div class="result" id="result" aria-live="polite"></div>
                </form>
              </section>
            </div>
          </main>
        `;
      }

      function QuestionCard(question, index) {
        return `
          <div class="form-field">
            <div class="question-head">
              <div>
                <h2 class="question-title">${index + 1}. ${question.title}</h2>
                ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
              </div>
            </div>
            <div class="option-grid">
              ${question.options
                .map(
                  (option) => `
                    <label class="option">
                      <input
                        type="checkbox"
                        name="${question.id}"
                        value="${option}"
                        data-correct="${question.correct.includes(option)}"
                      />
                      <span>${option}</span>
                    </label>
                  `
                )
                .join("")}
            </div>
          </div>
        `;
      }

      function renderApp() {
        document.getElementById("root").innerHTML = App();
        document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
      }

      function handleSubmit(event) {
        event.preventDefault();

        const result = document.getElementById("result");
        const formData = new FormData(event.currentTarget);
        let score = 0;

        quizData.forEach((question) => {
          const selected = formData.getAll(question.id);
          const correct = question.correct;
          const isPerfectMatch =
            selected.length === correct.length &&
            selected.every((value) => correct.includes(value)) &&
            correct.every((value) => selected.includes(value));

          if (isPerfectMatch) score += 1;
        });

        result.style.display = "block";
        result.innerHTML = `<strong>Quiz submitted.</strong>You got ${score} out of ${quizData.length} questions exactly right.`;
      }

      renderApp();
